		// default branch, auto-commit, push, advance. Later command
		// stages run their own commands after the merge, so a
		// merge-stage failure is always a git failure.
		return await executeMergeStage(store, {
			projectId,
			taskId,
			stage,
			stages,
			cwd,
			bridge,
			projectName,
		});
	}

