	task.history.push({
		timestamp: new Date().toISOString(),
		action: `Dispatched stage ${stage.name || stage.id} (${stageType}) with model ${stage.model || "default"}`,
	});
	_appendProcessLog(
		task,
		`[AGENT] Dispatched stage ${stage.name || stage.id} (${stageType}) with model ${stage.model || "default"}`,
	);
