		setTimeout(() => {
			store.scheduleTick().catch(() => {});
		}, 50);
	}

	return {
		task,
		stageType,
		status: "passed",
		output: finalOutput || streamedOutput,
		summary,
		modifiedFiles,
		model: stage.model || null,
		duration,
	};
}

